from django.db import migrations, models


def switch_to_usd(apps, schema_editor):
    """Existing accounts move to US dollars, except any with open or pending trades
    (their profit conversions were recorded in the old currency); those can be
    switched in the admin once the trades are closed."""
    TradingAccount = apps.get_model('trading', 'TradingAccount')
    for account in TradingAccount.objects.exclude(currency='USD'):
        if not account.trades.filter(status__in=['open', 'pending']).exists():
            account.currency = 'USD'
            account.save(update_fields=['currency'])


